//! Writes the published API schema to stdout.
//!
//! `docs/api/session-protocol.schema.json` is this program's checked-in output,
//! regenerated by `scripts/generate-api-schema.sh` and compared in CI. Nobody
//! edits that file: it is generated from the types in `termiod::protocol` so a
//! message the daemon can answer and a message the schema describes are the
//! same set by construction.

use schemars::schema_for;
use termiod::protocol::{Control, Event, PROTOCOL_VERSION, SUPPORTED_PROTOCOLS};

fn main() -> anyhow::Result<()> {
    let document = serde_json::json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "Termio Session Protocol",
        "description": "The framed messages clients exchange with termiod. \
                        Framing is [kind: u8][len: u32 big-endian][payload]; \
                        control and event payloads are the JSON described here. \
                        See https://termio.sh/docs/session-protocol.",
        "protocol": PROTOCOL_VERSION,
        "supported_protocols": SUPPORTED_PROTOCOLS,
        "frame_kinds": {
            "C": "control — the JSON in $defs.Control",
            "D": "data — raw PTY bytes, not JSON",
            "R": "viewport — one attachment's rows and cols, four or five bytes",
            "E": "event — the JSON in $defs.Event",
            "S": "snapshot — packed cells or VT sequences, not JSON",
            "H": "history — scrollback chunk, not JSON",
            "G": "grid — grid diff payload, not JSON",
            "F": "file — file chunk, not JSON",
            "U": "upload — upload chunk, not JSON"
        },
        "schemas": {
            "control": schema_for!(Control),
            "event": schema_for!(Event),
        }
    });
    println!("{}", serde_json::to_string_pretty(&document)?);
    Ok(())
}
